package capability

// The hand-written half of the applet help: what the matrix cannot know.
//
// Held to the matrix by usage_test.go, in both directions -- every applet needs an
// entry, every accepted option needs a gloss, and a gloss for an option that does
// not exist is a failure. That is what stops this file from becoming a list of
// claims nobody checks, which is the failure mode docs/design/reference-methodology
// exists to guard against.
//
// The glosses describe *this build*, not GNU's. Where the two differ the Notes say
// so, because a reader who knows GNU's version will assume the rest.
var usageText = map[string]Usage{
	"base64": {
		Summary:  "Encode or decode base64.",
		Operands: "[FILE]...",
		Options:  map[string]string{"d": "decode", "i": "when decoding, ignore characters that are not base64", "w": "wrap encoded lines at this column, 0 for no wrapping"},
	},
	"basename": {
		Summary:  "Strip directory and suffix from a path.",
		Operands: "NAME [SUFFIX]",
		Options:  map[string]string{"a": "treat every operand as a name, so several can be stripped at once"},
	},
	"cat": {
		Summary:  "Copy files to standard output.",
		Operands: "[FILE]...",
		Options:  map[string]string{"n": "number the output lines"},
		Notes:    []string{"A FILE of - is standard input."},
	},
	"chmod":     {Summary: "Change file mode bits.", Operands: "MODE FILE..."},
	"clear":     {Summary: "Clear the terminal screen."},
	"cmp":       {Summary: "Compare two files byte by byte.", Operands: "FILE1 [FILE2]", Options: map[string]string{"s": "say nothing; report only through the exit status", "l": "list the offset and the two bytes of every difference"}},
	"comm":      {Summary: "Compare two sorted files line by line, in three columns.", Operands: "FILE1 FILE2", Options: map[string]string{"1": "suppress column 1, the lines only in FILE1", "2": "suppress column 2, the lines only in FILE2", "3": "suppress column 3, the lines in both"}},
	"cp":        {Summary: "Copy files and directories.", Operands: "SOURCE... DEST", Options: map[string]string{"r": "copy directories and their contents", "R": "the same as -r"}},
	"cut":       {Summary: "Print selected parts of each line.", Operands: "[FILE]...", Options: map[string]string{"b": "select these byte positions", "c": "select these character positions", "d": "use this field delimiter instead of tab", "f": "select these fields", "n": "accepted and ignored, as it is by GNU cut without a multibyte locale", "s": "with -f, skip lines that hold no delimiter"}},
	"date":      {Summary: "Print the date and time.", Operands: "[+FORMAT]", Options: map[string]string{"d": "print this time rather than now", "u": "work in UTC"}},
	"dirname":   {Summary: "Strip the last component from a path.", Operands: "NAME..."},
	"du":        {Summary: "Report how much space files use.", Operands: "[FILE]...", Options: map[string]string{"s": "one total per operand rather than a line per file", "h": "print sizes in powers of 1024, as K, M and G"}},
	"echo":      {Summary: "Write arguments to standard output.", Operands: "[ARG]...", Options: map[string]string{"n": "no trailing newline", "e": "interpret backslash escapes"}, Notes: []string{"echo does not answer --help, because an argument is data: `echo --help` prints it."}},
	"env":       {Summary: "Run a command in a modified environment, or print the environment.", Operands: "[NAME=VALUE]... [COMMAND [ARG]...]", Options: map[string]string{"i": "start from an empty environment"}, Notes: []string{"COMMAND is resolved among this shell's applets only, not on PATH."}},
	"expr":      {Summary: "Evaluate an expression and print the result.", Operands: "EXPRESSION", Notes: []string{"Operators that the shell would take for its own -- ( ) * < > | & -- have to be quoted."}},
	"false":     {Summary: "Do nothing and fail."},
	"find":      {Summary: "Walk a directory tree and print what is there.", Operands: "[PATH]... [EXPRESSION]"},
	"grep":      {Summary: "Print the lines that match a pattern.", Operands: "PATTERN [FILE]...", Options: map[string]string{"i": "match without regard to case", "n": "prefix each line with its line number", "v": "print the lines that do not match", "r": "search directories, following no symlinks", "R": "the same as -r", "l": "print only the names of the files that match", "c": "print only how many lines matched", "q": "print nothing; report through the exit status", "w": "match whole words only", "x": "match whole lines only", "F": "take the pattern as a literal string, not a regular expression", "o": "print only the matching part of each line", "s": "do not report unreadable files", "h": "never prefix a line with its file name", "H": "always prefix a line with its file name", "E": "take the pattern as an extended regular expression", "m": "stop after this many matching lines", "color": "colour the matching part when the output is a terminal"}},
	"head":      {Summary: "Print the beginning of each file.", Operands: "[FILE]...", Options: map[string]string{"n": "print this many lines instead of 10", "c": "print this many bytes instead"}},
	"id":        {Summary: "Print the current user's identity.", Operands: "[USER]", Options: map[string]string{"u": "print only the user id", "g": "print only the primary group id", "G": "print every group id", "n": "with -u, -g or -G, print names rather than numbers"}},
	"ln":        {Summary: "Make a link to a file.", Operands: "TARGET LINK", Options: map[string]string{"s": "make a symbolic link rather than a hard one"}},
	"ls":        {Summary: "List directory contents.", Operands: "[FILE]...", Options: map[string]string{"a": "include names beginning with a dot", "h": "with -l, print sizes as K, M and G", "l": "one file per line, with mode, size and time", "1": "one name per line", "color": "colour the names by kind when the output is a terminal"}},
	"md5sum":    {Summary: "Print or check MD5 digests.", Operands: "[FILE]...", Options: map[string]string{"b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}, Notes: []string{"MD5 is broken for anything security-related; this is for comparing files."}},
	"mkdir":     {Summary: "Create directories.", Operands: "DIRECTORY...", Options: map[string]string{"m": "set the mode of the new directory", "p": "create missing parents, and do not fail if it exists", "v": "print a line per directory created"}},
	"mktemp":    {Summary: "Create a temporary file or directory and print its name.", Operands: "[TEMPLATE]", Options: map[string]string{"d": "create a directory rather than a file", "q": "say nothing when it cannot", "u": "print a name without creating anything"}, Notes: []string{"-u is unsafe by nature: the name it prints is not reserved."}},
	"mv":        {Summary: "Move or rename files.", Operands: "SOURCE... DEST", Options: map[string]string{"f": "do not ask before replacing an existing file"}},
	"nl":        {Summary: "Number the lines of each file.", Operands: "[FILE]...", Options: map[string]string{"b": "which lines to number: a for all, t for the non-empty ones, n for none"}},
	"paste":     {Summary: "Join corresponding lines of files side by side.", Operands: "[FILE]...", Options: map[string]string{"s": "paste each file as one line rather than in parallel", "d": "use these characters as separators in turn instead of tab"}},
	"pgrep":     {Summary: "Find processes by name.", Operands: "PATTERN", Options: map[string]string{"l": "print the name beside the process id", "x": "match the whole name rather than part of it"}},
	"pkill":     {Summary: "Signal processes by name.", Operands: "PATTERN", Options: map[string]string{"x": "match the whole name rather than part of it"}},
	"posixpath": {Summary: "Print the shell's spelling of a host path.", Operands: "PATH...", Notes: []string{"The inverse of winpath. See docs/design/windows-path-model.md."}},
	"printenv":  {Summary: "Print environment variables.", Operands: "[NAME]..."},
	"printf":    {Summary: "Format and print arguments.", Operands: "FORMAT [ARG]...", Notes: []string{"Conversions: %s %d %i %u %o %x %X %c %b %q %% and \\ escapes.", "The format is reused until the arguments run out, as POSIX requires."}},
	"ps": {Summary: "Report the processes running now.", Notes: []string{
		"Columns: PID PPID THR RSS TIME COMMAND.",
		"No TTY column: Windows has no controlling terminal.",
		"No USER or command line: both need a handle on the process, which is refused",
		"for anything this session does not own.",
	}},
	"pwd":      {Summary: "Print the working directory.", Options: map[string]string{"L": "print it as the shell remembers it, symlinks and all", "P": "resolve every symlink first"}},
	"readlink": {Summary: "Print what a symbolic link points at.", Operands: "FILE...", Options: map[string]string{"n": "no trailing newline"}},
	"realpath": {Summary: "Resolve a path to an absolute one with no symlinks.", Operands: "FILE..."},
	"rev":      {Summary: "Reverse the characters of every line.", Operands: "[FILE]..."},
	"rm":       {Summary: "Remove files and directories.", Operands: "FILE...", Options: map[string]string{"f": "do not complain about what is not there", "r": "remove directories and their contents"}},
	"rmdir":    {Summary: "Remove empty directories.", Operands: "DIRECTORY...", Options: map[string]string{"p": "remove each parent that becomes empty too", "v": "print a line per directory removed"}},
	"sed": {Summary: "Edit a stream of text by script.", Operands: "SCRIPT [FILE]...", Notes: []string{
		"Only the s command: s/PATTERN/REPLACEMENT/[g][N].",
		"PATTERN is a POSIX basic regular expression, with the GNU \\+ \\? \\| extensions.",
		"REPLACEMENT takes & for the whole match and \\1 to \\9 for a group.",
		"A backreference in the PATTERN is refused: this build matches with RE2, which has none.",
	}},
	"seq":        {Summary: "Print a sequence of numbers.", Operands: "[FIRST [INCREMENT]] LAST"},
	"sha256sum":  {Summary: "Print or check SHA-256 digests.", Operands: "[FILE]...", Options: map[string]string{"b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}},
	"sha1sum":    {Summary: "Print or check SHA-1 digests.", Operands: "[FILE]...", Options: map[string]string{"b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}, Notes: []string{"SHA-1 is broken for anything security-related; this is for comparing files."}},
	"sha384sum":  {Summary: "Print or check SHA-384 digests.", Operands: "[FILE]...", Options: map[string]string{"b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}},
	"sha512sum":  {Summary: "Print or check SHA-512 digests.", Operands: "[FILE]...", Options: map[string]string{"b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}},
	"sha3sum":    {Summary: "Print or check SHA-3 digests.", Operands: "[FILE]...", Options: map[string]string{"a": "the width in bits: 224, 256, 384 or 512", "b": "read in binary mode, and mark it with a * in the output", "c": "read the operands as lists of digests and check them", "t": "read in text mode, which is the default", "w": "with -c, warn about lines that are not a digest"}, Notes: []string{"The default width is 224 bits, which is what busybox does. SHA-3 is a different function from SHA-2, not a truncation of it."}},
	"free":       {Summary: "Show how much memory the machine has and how much is free.", Options: map[string]string{"b": "in bytes", "k": "in kilobytes, which is the default", "m": "in megabytes", "g": "in gigabytes", "h": "accepted; the columns are already aligned"}, Notes: []string{"The Swap row is Windows' commit charge rather than a swap file: there is no swap partition to measure, and commit is the number that says whether the next allocation will be refused. The shared column is always zero because Windows has no equivalent counter."}},
	"factor":     {Summary: "Print the prime factors of each number.", Operands: "[NUMBER]..."},
	"fold":       {Summary: "Wrap each line to a width.", Operands: "[FILE]...", Options: map[string]string{"w": "wrap at this many characters instead of 80", "s": "prefer to break at a space", "b": "count bytes rather than columns"}},
	"tsort":      {Summary: "Sort items so that each comes before the ones that depend on it.", Operands: "[FILE]...", Notes: []string{"Input is pairs: `before after`. A cycle is reported rather than silently truncated, because a partial order looks exactly like a complete one."}},
	"strings":    {Summary: "Print the runs of printable characters in a file.", Operands: "[FILE]...", Options: map[string]string{"n": "the shortest run to report, default 4", "t": "prefix the offset in this radix: d, o, x or X", "o": "the same as -t o", "a": "scan the whole file, which is already what this does", "f": "accepted"}},
	"ascii":      {Summary: "Print the ASCII character table."},
	"expand":     {Summary: "Convert tabs to spaces.", Operands: "[FILE]...", Options: map[string]string{"t": "tab stops this far apart instead of 8", "i": "stop converting after the first non-blank"}},
	"unexpand":   {Summary: "Convert spaces to tabs.", Operands: "[FILE]...", Options: map[string]string{"t": "tab stops this far apart instead of 8", "a": "convert throughout, not only the leading blanks"}},
	"join":       {Summary: "Join two files on a common field.", Operands: "FILE1 FILE2", Options: map[string]string{"j": "join on this field in both files", "1": "join on this field of the first file", "2": "join on this field of the second", "t": "the field separator"}},
	"base32":     {Summary: "Encode or decode base32.", Operands: "[FILE]...", Options: map[string]string{"d": "decode", "i": "when decoding, skip characters that are not base32", "w": "wrap at this column instead of 76; 0 does not wrap"}},
	"shuf":       {Summary: "Print the input lines in a random order.", Operands: "[FILE]...", Options: map[string]string{"n": "print at most this many", "e": "treat the operands as the input lines", "i": "use the numbers in this inclusive range", "z": "separate with NUL rather than newline"}},
	"dos2unix":   {Summary: "Convert CRLF line endings to LF.", Operands: "[FILE]...", Options: map[string]string{"u": "convert to Unix endings, which is this name's direction", "d": "convert to DOS endings instead"}, Notes: []string{"A file operand is converted IN PLACE and nothing is written to stdout. With no operand it filters stdin to stdout. A lone carriage return is left alone: only the CR of a CRLF is removed."}},
	"unix2dos":   {Summary: "Convert LF line endings to CRLF.", Operands: "[FILE]...", Options: map[string]string{"d": "convert to DOS endings, which is this name's direction", "u": "convert to Unix endings instead"}, Notes: []string{"A file operand is converted IN PLACE. Running it twice is safe: the input is normalised to LF first, so no CR is ever doubled."}},
	"iconv":      {Summary: "Convert text between character encodings.", Operands: "[FILE]...", Options: map[string]string{"f": "the encoding to read", "t": "the encoding to write", "l": "list the encodings this build knows", "c": "drop characters the target cannot represent", "o": "write to this file rather than stdout"}, Notes: []string{"An encoding is named, never guessed, for the same reason grep only honours a byte-order mark: guessing is how a binary gets rewritten. Both default to UTF-8. No BOM is written unless the named encoding is one of the explicit BOM forms."}},
	"gzip":       {Summary: "Compress files with gzip.", Operands: "[FILE]...", Options: map[string]string{"c": "write to stdout and leave the file alone", "d": "decompress", "f": "overwrite an existing companion file", "k": "keep the input file", "t": "test integrity without writing anything", "1": "fastest", "2": "level 2", "3": "level 3", "4": "level 4", "5": "level 5", "6": "level 6, the default", "7": "level 7", "8": "level 8", "9": "smallest"}, Notes: []string{"With a file operand the file is REPLACED by its .gz companion and the original removed, unless -k or -c. Stock Windows has no gzip, and tar.exe cannot stand in: these are stream filters."}},
	"gunzip":     {Summary: "Decompress gzip files.", Operands: "[FILE]...", Options: map[string]string{"c": "write to stdout and leave the file alone", "d": "decompress", "f": "overwrite an existing companion file", "k": "keep the input file", "t": "test integrity without writing anything", "1": "fastest", "2": "level 2", "3": "level 3", "4": "level 4", "5": "level 5", "6": "level 6, the default", "7": "level 7", "8": "level 8", "9": "smallest"}},
	"zcat":       {Summary: "Decompress gzip files to stdout.", Operands: "[FILE]...", Options: map[string]string{"c": "write to stdout and leave the file alone", "d": "decompress", "f": "overwrite an existing companion file", "k": "keep the input file", "t": "test integrity without writing anything", "1": "fastest", "2": "level 2", "3": "level 3", "4": "level 4", "5": "level 5", "6": "level 6, the default", "7": "level 7", "8": "level 8", "9": "smallest"}},
	"bunzip2":    {Summary: "Decompress bzip2 files.", Operands: "[FILE]...", Options: map[string]string{"c": "write to stdout and leave the file alone", "d": "decompress", "f": "overwrite an existing companion file", "k": "keep the input file", "t": "test integrity without writing anything", "1": "fastest", "2": "level 2", "3": "level 3", "4": "level 4", "5": "level 5", "6": "level 6, the default", "7": "level 7", "8": "level 8", "9": "smallest"}, Notes: []string{"Decompression only. The standard library cannot compress bzip2, so `bzip2` is not provided at all rather than refused -- which leaves PATH free to find a real one."}},
	"bzcat":      {Summary: "Decompress bzip2 files to stdout.", Operands: "[FILE]...", Options: map[string]string{"c": "write to stdout and leave the file alone", "d": "decompress", "f": "overwrite an existing companion file", "k": "keep the input file", "t": "test integrity without writing anything", "1": "fastest", "2": "level 2", "3": "level 3", "4": "level 4", "5": "level 5", "6": "level 6, the default", "7": "level 7", "8": "level 8", "9": "smallest"}},
	"tar":        {Summary: "Create, list or extract a tar archive.", Operands: "[FILE]...", Options: map[string]string{"c": "create", "t": "list", "x": "extract", "v": "name each entry", "z": "through gzip", "j": "through bzip2, decompressing only", "a": "choose the compression from the archive name", "O": "extract to stdout", "f": "the archive, or - for stdin", "C": "change to this directory first"}, Notes: []string{"An archive names its own destinations, so extraction treats every entry as untrusted: a name that escapes the root, is absolute or drive-qualified, contains a backslash, is a Windows reserved device name, or collides case-insensitively with an earlier entry is skipped with the reason. Listing does not check, because listing is how a suspicious archive is inspected."}},
	"cpio":       {Summary: "Create, list or extract a cpio archive.", Operands: "[PATTERN]...", Options: map[string]string{"t": "list", "i": "extract", "o": "create from the names on stdin", "d": "make leading directories when extracting", "m": "restore the stored mtime", "v": "name each entry", "u": "overwrite an existing file", "0": "read NUL-separated names, as find -print0 writes", "F": "the archive, instead of stdin or stdout", "H": "the format; only newc is written"}, Notes: []string{"Exactly one of -t, -i and -o is required. cpio archives the *list* of names on its stdin rather than descending a tree, which is what pairs it with find and what distinguishes it from tar. Only the newc header and its CRC variant are read; the older octal and raw-binary headers are refused by magic rather than misread. Extraction treats every entry as untrusted, exactly as tar does."}},
	"ar":         {Summary: "Create, list or extract an ar archive.", Operands: "ARCHIVE [FILE]...", Options: map[string]string{"x": "extract", "p": "extract to stdout", "t": "list", "r": "create", "o": "restore the stored mtime", "v": "name each entry"}, Notes: []string{"The operation is a verb rather than an option -- `ar t lib.a` -- and the dashed spelling is accepted too. A .deb is an ar archive holding debian-binary and two tars, which is the reason to have this. -r creates and refuses an archive that already exists: adding to one means rewriting the long-name table, and a half-done version of that corrupts the archive it was given. Long names are read and not written, and every member of an ar archive is a plain file."}},
	"unzip":      {Summary: "List, test or extract a zip archive.", Operands: "ARCHIVE [FILE]...", Options: map[string]string{"l": "list", "t": "test without writing", "p": "extract to stdout", "j": "discard the stored directories", "n": "never overwrite", "o": "always overwrite", "q": "quieter", "K": "accepted; there is no SUID bit here", "d": "extract into this directory", "x": "skip entries matching this pattern"}, Notes: []string{"An operand is required: zip keeps its central directory at the end of the file, so it cannot be read from a pipe. With neither -o nor -n an existing file is left alone and said so, because there is no prompt to ask at."}},
	"nano":       {Summary: "Edit a file, with nano's key bindings.", Operands: "[FILE]", Options: map[string]string{"H": "list the features this build implements", "R": "open read-only"}, Notes: []string{"One editor under two names: nano binds ^O ^X ^W ^K ^U ^G, micro binds ^S ^Q ^F ^K ^V ^G. A subset, and -H lists exactly which -- in the manner of `busybox vi -H`, whose own vi is a 3000-line clone that says so."}},
	"micro":      {Summary: "Edit a file, with micro's key bindings.", Operands: "[FILE]", Options: map[string]string{"H": "list the features this build implements", "R": "open read-only"}, Notes: []string{"The same editor as nano with a Windows-shaped key map: ^S saves, ^Q quits, ^F finds. -H lists what is implemented and what is not."}},
	"od":         {Summary: "Dump a file in octal or hex.", Operands: "[FILE]...", Options: map[string]string{"b": "octal bytes", "c": "characters, with escapes", "C": "hex bytes with an ASCII gutter", "d": "decimal", "o": "octal words", "x": "hex words", "v": "accepted; identical lines are never folded here", "A": "the address radix: o, d, x, or n for none", "t": "the output type: x1, x2, o2, c"}, Notes: []string{"The word forms read each byte pair little-endian, so `he` prints as 6568 rather than 6865 -- the most surprising thing about either tool. od defaults to octal offsets and octal words; hexdump to hex; hd to `hexdump -C`."}},
	"hexdump":    {Summary: "Dump a file in hex.", Operands: "[FILE]...", Options: map[string]string{"b": "octal bytes", "c": "characters, with escapes", "C": "hex bytes with an ASCII gutter", "d": "decimal", "o": "octal words", "x": "hex words", "v": "accepted; identical lines are never folded here", "A": "the address radix: o, d, x, or n for none", "t": "the output type: x1, x2, o2, c"}, Notes: []string{"The word forms read each byte pair little-endian, so `he` prints as 6568 rather than 6865 -- the most surprising thing about either tool. od defaults to octal offsets and octal words; hexdump to hex; hd to `hexdump -C`."}},
	"hd":         {Summary: "Dump a file in canonical hex.", Operands: "[FILE]...", Options: map[string]string{"b": "octal bytes", "c": "characters, with escapes", "C": "hex bytes with an ASCII gutter", "d": "decimal", "o": "octal words", "x": "hex words", "v": "accepted; identical lines are never folded here", "A": "the address radix: o, d, x, or n for none", "t": "the output type: x1, x2, o2, c"}, Notes: []string{"The word forms read each byte pair little-endian, so `he` prints as 6568 rather than 6865 -- the most surprising thing about either tool. od defaults to octal offsets and octal words; hexdump to hex; hd to `hexdump -C`."}},
	"uuencode":   {Summary: "Encode a file for a text-only channel.", Operands: "[FILE] NAME", Options: map[string]string{"m": "not implemented; use base64 instead"}, Notes: []string{"The last operand is the name recorded in the header, which is where uudecode will write. A zero-length group encodes as a backtick rather than a space, because trailing spaces do not survive mail."}},
	"uudecode":   {Summary: "Decode a uuencoded file.", Operands: "[FILE]...", Options: map[string]string{"o": "write here instead of the name in the header; - is stdout"}, Notes: []string{"The name in the header came from the sender, so it is checked the way an archive entry is: `begin 644 ../../evil` is the same attack a tar entry would be."}},
	"diff":       {Summary: "Compare two files line by line.", Operands: "FILE1 FILE2", Options: map[string]string{"u": "unified output, which is already the default", "U": "this many lines of context instead of 3", "q": "report only whether they differ", "s": "report when they are identical", "i": "ignore case", "w": "ignore differences in whitespace", "B": "ignore blank lines", "N": "treat an absent file as empty", "L": "use this label in the header", "r": "accepted", "a": "accepted", "b": "accepted", "d": "accepted", "T": "accepted", "t": "accepted"}, Notes: []string{"The output is unified always, which is busybox's default rather than GNU's. The header carries no timestamps, so two runs over unchanged files produce identical output. Status is 0 when they match, 1 when they differ, 2 on a failure to compare."}},
	"patch":      {Summary: "Apply a unified diff.", Operands: "[FILE]", Options: map[string]string{"i": "read the diff from this file rather than stdin", "p": "strip this many leading path components from the names in the diff", "R": "apply the diff in reverse", "N": "accepted", "E": "accepted", "f": "accepted", "l": "accepted"}, Notes: []string{"A hunk that does not match is refused with its line number and the text that was found instead. There is no fuzz: shifting a hunk until the context happens to line up is how a patch lands where it was never meant to, and the wrong place usually still compiles. The names in the diff come from whoever wrote it, so they are checked the way an archive entry is."}},
	"wget":       {Summary: "Fetch a URL over HTTP or HTTPS.", Operands: "URL...", Options: map[string]string{"O": "write here; - is stdout", "P": "save into this directory", "U": "the User-Agent to send", "T": "give up after this many seconds", "q": "quieter", "S": "print the server's status line", "c": "accepted; resuming is not implemented", "o": "accepted", "header": "send this header; repeatable", "spider": "ask whether the URL is there and download nothing"}, Notes: []string{"TLS is native, so unlike busybox this needs no ssl_client helper. The saved name comes from the URL, and the server chose that, so it is checked the way an archive entry is. A 4xx or 5xx is a failed download rather than a file whose contents are the error page."}},
	"nc":         {Summary: "Open a pipe to a TCP address.", Operands: "[HOST PORT]", Options: map[string]string{"l": "listen for one connection instead of dialling", "p": "the local port to listen on", "w": "give up connecting after this many seconds"}, Notes: []string{"Listening binds 127.0.0.1 unless an address is given: a listener reachable from the network is a decision, not a default. -e is refused, because running a program on a connection is a remote shell."}},
	"whois":      {Summary: "Look a name up in a WHOIS registry.", Operands: "NAME...", Options: map[string]string{"h": "ask this server", "p": "use this port instead of 43", "i": "accepted"}, Notes: []string{"The server is chosen from the name's last label, falling back to IANA -- whose answer names the registry to ask next."}},
	"ssl_client": {Summary: "Open a TLS pipe to a host.", Operands: "HOST [PORT]", Options: map[string]string{"s": "the host to connect to", "h": "the same as -s", "n": "the SNI name to send", "e": "accepted"}, Notes: []string{"The certificate is always verified; there is no option to skip it, because a TLS pipe that does not check the certificate is a plaintext pipe wearing a costume. nemosh's own wget does not use this -- Go speaks TLS natively -- so it is here for what the name means: openssl s_client without openssl."}},
	"httpd":      {Summary: "Serve a directory over HTTP.", Options: map[string]string{"h": "the directory to serve, default .", "p": "the port, default 8080", "a": "the address to bind, default 127.0.0.1", "v": "log each request", "f": "accepted; this always runs in the foreground"}, Notes: []string{"Binds loopback unless -a says otherwise, where busybox binds every interface: reaching the network is a decision. No CGI, because that turns a file server into an execution service. Every request path goes through the same containment check the archivers use, so it cannot escape the root, name a Windows device, or reach a .. after normalisation."}},
	"ftpget":     {Summary: "Download one file over FTP.", Operands: "HOST [LOCAL] REMOTE", Options: map[string]string{"u": "the user, default anonymous", "p": "the password", "P": "the port, default 21", "v": "trace the control connection", "c": "accepted; resuming is not implemented"}, Notes: []string{"Passive mode only: active mode asks the server to connect back, which no machine behind a router or a Windows firewall can accept."}},
	"ftpput":     {Summary: "Upload one file over FTP.", Operands: "HOST [REMOTE] LOCAL", Options: map[string]string{"u": "the user, default anonymous", "p": "the password", "P": "the port, default 21", "v": "trace the control connection", "c": "accepted"}},
	"cksum":      {Summary: "Print the POSIX CRC and byte count of each file.", Operands: "[FILE]...", Notes: []string{"Not the same CRC as crc32: cksum walks a different polynomial and feeds the file length through it, so the two disagree for the same bytes."}},
	"crc32":      {Summary: "Print the CRC-32 of each file, in hex.", Operands: "[FILE]..."},
	"sum":        {Summary: "Print a 16-bit checksum and block count for each file.", Operands: "[FILE]...", Options: map[string]string{"r": "the BSD algorithm in 1024-byte blocks, which is the default", "s": "the System V algorithm in 512-byte blocks"}, Notes: []string{"The two algorithms disagree for the same file, which is why the option exists."}},
	"sleep":      {Summary: "Wait for a while.", Operands: "SECONDS"},
	"sort":       {Summary: "Sort lines of text.", Operands: "[FILE]...", Options: map[string]string{"n": "compare as numbers rather than as text", "r": "reverse the result", "u": "print only the first of an equal run", "f": "fold case when comparing", "b": "ignore leading blanks", "k": "sort on this key rather than the whole line", "t": "use this character as the field separator"}},
	"split":      {Summary: "Split a file into pieces.", Operands: "[FILE [PREFIX]]", Options: map[string]string{"l": "put this many lines in each piece"}},
	"stat":       {Summary: "Report what the filesystem knows about a file.", Operands: "FILE...", Options: map[string]string{"c": "print in this format rather than the default one"}},
	"su":         {Summary: "Run a shell with administrator rights.", Operands: "[root]", Options: map[string]string{"c": "run this command in the elevated shell instead of an interactive one", "s": "use this shell rather than nemosh", "t": "test whether elevation would work, and report it; implies -W", "W": "wait for the elevated shell to finish", "N": "use this nemosh, which is the default and cannot be combined with -s"}, Notes: []string{"The only user it will become is root, which on Windows means an elevated session.", "A pipe or redirection around su cannot reach the elevated shell: Windows cannot", "pass handles across the elevation boundary. Use -c and redirect inside it."}},
	"tac":        {Summary: "Print the lines of each file in reverse order.", Operands: "[FILE]..."},
	"tail":       {Summary: "Print the end of each file.", Operands: "[FILE]...", Options: map[string]string{"n": "print this many lines instead of 10", "c": "print this many bytes instead"}, Notes: []string{"-f is not implemented; `tail -f` is refused rather than quietly finishing."}},
	"tee":        {Summary: "Copy standard input to each file and to standard output.", Operands: "[FILE]...", Options: map[string]string{"a": "append to the files rather than truncating them"}},
	"top": {
		Summary:  "Watch processes, CPU and memory as they change.",
		Operands: "",
		Options: map[string]string{
			"b": "plain output rather than a drawn table, which is also what a pipe gets",
			"n": "how many samples to print in plain mode",
			"d": "seconds between samples",
			"s": "start sorted by this column: cpu, mem, rss, thr, time, pid and the rest; `help` lists them",
			"f": "show only processes whose name or command line contains this",
			"H": "show threads as well as processes",
			"t": "arrange by parentage rather than sorting flat",
			"o": "show exactly these columns, comma separated, instead of the default; `help` lists them all with what each one means",
		},
		Notes: []string{
			"Needs no administrator rights: everything but the command line and the owning",
			"user comes from one system call that opens no process.",
			"The first sample reports 0.0 for every CPU figure, because a rate needs two.",
			"No load average: Windows has no such measure. The nearest analogue is the",
			"processor queue length, which counts something else, so nothing is shown.",
			"No TTY column either, for the reason ps gives: there is no controlling terminal.",
			"Keys follow htop: P M T N sort, space tags, +/- fold, Z pauses, p shows the",
			"full path, / searches and n repeats it, F4 filters, F7 and F8 change priority,",
			"F9 kills. F1 lists them",
			"while it is running. Searching leaves the list whole; filtering hides what",
			"does not match.",
			"F1 explains the columns, the meters and the colours, and says what is absent",
			"and why. `top -o help` prints the same column glossary without a terminal.",
			"The drawn table shows more columns in a wider window: IO bytes past 104 cells,",
			"IO operations and handle counts past 124. -o overrides that.",
			"The IO columns are IO and not disk. Windows counts every byte a process moves",
			"through any handle -- file, pipe, socket, console -- in one set of counters, so",
			"a process reading a pipe would read as a process hammering the drive. Disk-only",
			"figures need ETW and an administrator. See docs/design/process-view.md.",
		},
	},
	"touch":   {Summary: "Set a file's timestamps, creating it if it is absent.", Operands: "FILE...", Options: map[string]string{"c": "do not create anything that is not already there"}},
	"tr":      {Summary: "Translate, squeeze or delete characters.", Operands: "SET1 [SET2]", Options: map[string]string{"d": "delete the characters in SET1", "s": "squeeze each repeated run down to one character", "c": "act on the complement of SET1"}},
	"true":    {Summary: "Do nothing and succeed."},
	"uname":   {Summary: "Print information about the system.", Options: map[string]string{"a": "print everything below", "i": "the hardware platform", "m": "the machine's hardware name", "n": "the network node name", "o": "the operating system", "p": "the processor type", "r": "the release", "s": "the kernel name, which is what it prints with no options", "v": "the version"}},
	"uniq":    {Summary: "Report or omit repeated adjacent lines.", Operands: "[INPUT [OUTPUT]]", Options: map[string]string{"c": "prefix each line with how many times it repeated", "d": "print only the lines that repeated", "u": "print only the lines that did not", "i": "compare without regard to case"}, Notes: []string{"Only *adjacent* duplicates, so the input usually wants sorting first."}},
	"wc":      {Summary: "Count lines, words and bytes.", Operands: "[FILE]...", Options: map[string]string{"c": "count bytes", "l": "count lines", "w": "count words", "m": "count characters, which differs from -c outside ASCII", "L": "print the length of the longest line"}},
	"whoami":  {Summary: "Print the current user's name."},
	"winpath": {Summary: "Print the host's spelling of a shell path.", Operands: "PATH...", Notes: []string{"The inverse of posixpath. See docs/design/windows-path-model.md."}},
	"xargs":   {Summary: "Build and run command lines from standard input.", Operands: "[COMMAND [ARG]...]", Options: map[string]string{"0": "input is separated by NUL, which is what pairs with `find -print0`", "r": "do not run the command at all if the input is empty", "t": "print each command line before running it", "n": "pass at most this many arguments per run", "I": "replace this string in the command with one input line per run"}, Notes: []string{"-P is not implemented; parallel runs are refused rather than run one at a time."}},
	"xxd":     {Summary: "Make a hex dump.", Operands: "[FILE]", Options: map[string]string{"p": "plain dump: hex only, no offsets and no text column"}},
	"yes":     {Summary: "Print a string over and over until killed.", Operands: "[STRING]"},
	"test":    {Summary: "Evaluate a conditional expression.", Operands: "EXPRESSION", Notes: []string{"test does not answer --help, because an argument is data: `test --help` asks", "whether the string --help is non-empty, and it is."}},
	"[":       {Summary: "Evaluate a conditional expression; the last argument must be ].", Operands: "EXPRESSION ]"},
}
